{
  "core_question": "How should a 5,000‑employee self‑insured employer evaluate and decide on covering GLP‑1 medications for obesity versus type 2 diabetes, considering clinical evidence, legal compliance, and financial impact?",
  "rationale": "Clinical expertise is needed to assess efficacy, safety, and appropriate utilization criteria; legal guidance ensures ERISA/ACA compliance and anti‑discrimination considerations; finance analysis quantifies cost, savings, and budgetary implications.",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "For a self‑insured employer with 5,000 employees considering coverage of GLP‑1 agents (semaglutide, tirzepatide) for obesity rather than only type 2 diabetes, what current clinical evidence supports their use in obesity, what are the key safety considerations, and which utilization‑management criteria (e.g., BMI thresholds, prior weight‑loss attempts, comorbidity requirements) would best balance effectiveness with risk mitigation?",
    "legal": "Given a self‑insured employer with 5,000 employees evaluating coverage of GLP‑1 medications for obesity, what ERISA, ACA, and state‑level legal obligations or restrictions must be considered to ensure compliance (including anti‑discrimination, coverage mandates, and potential liability), and how should the plan design address these requirements?",
    "finance": "For a 5,000‑employee self‑insured employer deciding whether to cover GLP‑1 medications for obesity versus type 2 diabetes, what is the projected financial impact—including drug acquisition costs, expected rebates or discounts, utilization rates, potential savings from reduced obesity‑related health claims, and overall budgetary effect—under different coverage scenarios?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Current drug pricing, rebate structures, and utilization-management policies for GLP‑1 agents; latest FDA indications and labeling changes; recent CMS or state insurance regulations regarding obesity medication coverage."
}
